  "mode": "advice" | "edit" | "clarify",
  "summary": "一句话说清楚你要做什么，会显示给用户",
  "clarification": "仅 mode=clarify 时填写，问清楚缺的信息",
  "actions": [
    { "name": "工具名", "params": { "字段": "值" } }
  ]
